  margin-bottom: 10px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 50px;
}

.content_card-header {
  color: #082753;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 30px;
  display: flex;
}

.content_card-header.hide {
  display: none;
}

.content_card-info-text {
  background-color: #dae4d866;
  width: 100%;
  padding: .5rem 1rem;
  font-size: .875rem;
}

.content_card-list-wrapper {
  width: 100%;
}

.content_card-info-block {
  grid-column-gap: .5rem;
  grid-row-gap: .5rem;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  grid-auto-columns: 1fr;
  place-items: center start;
  display: grid;
}

.content_card-date {
  color: #3c7c43;
}

.content_card-info-label {
  font-size: .875rem;
  font-weight: 500;
}

.filter-bar-title {
  color: #092245;
